import React, { useState, useRef } from 'react';

interface WindowProps {
  id: string;
  title: string;
  content: any;
  onClose: (id: string) => void;
}

const Window: React.FC<WindowProps> = ({ id, title, content, onClose }) => {
  const [position, setPosition] = useState({ x: 100, y: 100 });
  const [size, setSize] = useState({ width: 400, height: 300 });
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const dragStartPos = useRef({ x: 0, y: 0 });
  const resizeStartPos = useRef({ x: 0, y: 0 });

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    dragStartPos.current = {
      x: e.clientX - position.x,
      y: e.clientY - position.y,
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging) {
      setPosition({
        x: e.clientX - dragStartPos.current.x,
        y: e.clientY - dragStartPos.current.y,
      });
    }
    if (isResizing) {
      setSize({
        width: e.clientX - resizeStartPos.current.x,
        height: e.clientY - resizeStartPos.current.y,
      });
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    setIsResizing(false);
  };

  const handleResizeMouseDown = (e: React.MouseEvent) => {
    setIsResizing(true);
    resizeStartPos.current = {
      x: e.clientX - size.width,
      y: e.clientY - size.height,
    };
  };

  return (
    <div
      className="window"
      style={{ top: position.y, left: position.x, width: size.width, height: size.height }}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
    >
      <div className="title-bar" onMouseDown={handleMouseDown}>
        <div className="title">{title}</div>
        <div className="window-buttons">
          <div className="window-button">-</div>
          <div className="window-button">[]</div>
          <div className="close-button" onClick={() => onClose(id)}>X</div>
        </div>
      </div>
      <div className="content">
        {Array.isArray(content) ? (
          content.map((item, index) => (
            <p key={index}>
              {typeof item === 'object' ? (
                <a href={item.type === 'email' ? `mailto:${item.value}` : `https://github.com/${item.value}`} target="_blank" rel="noopener noreferrer">{item.value}</a>
              ) : (
                item
              )}
            </p>
          ))
        ) : (
          <p>{content}</p>
        )}
      </div>
      <div className="resize-handle" onMouseDown={handleResizeMouseDown}></div>
    </div>
  );
};

export default Window;
